declarations.code:
friend constexpr difference_type operator-(std::default_sentinel_t s,

    const /*outer-iterator*/ &i)

    requires ranges::sized_sentinel_for<ranges::sentinel_t<V>,

        ranges::iterator_t<V>>;

intro:
Calculates the distance (in number of chunks) between the iterator and sentinel.

Let parent_ be the underlying pointer to enclosing chunk_view.

1) Equivalent to:
const auto dist = ranges::end(i.parent_->base_) - *i.parent_->current_;
if (dist < i.parent_->remainder_)
    return dist == 0 ? 0 : 1;
return /*div-ceil*/(dist - i.parent_->remainder_, i.parent_->n_) + 1;

2) Equivalent to: return -(s - i);.

These functions are not visible to ordinary unqualified or qualified lookup, and can only be found by argument-dependent lookup when std::ranges::chunk_view::outer-iterator is an associated class of the arguments.

recommendedExamples.code:
#include <iostream>
#include <iterator>
#include <ranges>
#include <sstream>

int main() {
    const std::string source{"ABCDEFGHIJ"};

    auto letters = std::istringstream{source};
    auto chunks = std::ranges::istream_view<char>(letters) | std::views::chunk(4);

    for (auto outer_iter = chunks.begin(); outer_iter != std::default_sentinel;
        ++outer_iter) {
        auto chunk = *outer_iter; // chunk is an object of type
                                  // chunk_view::outer_iterator::value_type
        std::cout << '[';
        for (auto inner_iter = chunk.begin(); inner_iter != std::default_sentinel;
            ++inner_iter)
            std::cout << *inner_iter;
        std::cout << "] ";
    }
    std::cout << '\n';

    // The same output using range-for loops
    auto letters2 = std::istringstream{source};
    auto chunks2 = std::ranges::istream_view<char>(letters2) | std::views::chunk(4);
    for (auto chunk : chunks2) {
        std::cout << '[';
        for (auto ch : chunk)
            std::cout << ch;
        std::cout << "] ";
    }
    std::cout << '\n';
}
